        if "minItems" in s and len(inst) < s["minItems"]:
            errs.append(f"{here}: fewer than {s['minItems']} items")
        if "maxItems" in s and len(inst) > s["maxItems"]:
            errs.append(f"{here}: more than {s['maxItems']} items")
