    },
    "quantity": {
      "type": "string",
      "pattern": "^[0-9]+(Mi|Gi)$"
    },
    "labels": {
      "type": "object",
      "patternProperties": {
        "^[a-z0-9./-]+$": {
          "type": "string"
        }
      },
      "additionalProperties": false
    }
