  "type": "object",
  "additionalProperties": false,
  "properties": {
    "service": {
      "type": "object",
      "required": [
        "port"
      ],
      "additionalProperties": false,
      "properties": {
        "port": {
          "$ref": "#/$defs/port"
        }
      }
    },
    "metrics": {
      "type": "object",
      "required": [
        "enabled"
      ],
      "additionalProperties": false,
      "properties": {
        "enabled": {
          "type": "boolean"
        },
        "port": {
          "$ref": "#/$defs/port"
        }
      }
    },
    "podLabels": {
      "$ref": "#/$defs/labels"
    },
    "podAnnotations": {
      "$ref": "#/$defs/labels"
    },
    "persistence": {
      "oneOf": [
        {
          "type": "object",
          "required": [
            "enabled"
          ],
          "additionalProperties": false,
          "properties": {
            "enabled": {
              "const": false
            }
          }
        },
        {
          "type": "object",
          "required": [
            "enabled",
            "size"
          ],
          "additionalProperties": false,
          "properties": {
            "enabled": {
              "const": true
            },
            "size": {
              "$ref": "#/$defs/quantity"
            },
            "storageClass": {
              "type": "string"
            }
          }
        }
      ]
    }
  }
}

